#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=11

# ── scripts/deploy-wizard.sh ──────────────────────────────────────────────
# The owner-only half of the first deploy (README → Deployment → Set it up): the Fly account and
# card, the app, its secrets, the first `fly deploy --ha=false`, the Vercel import, CORS, the
# post-deploy checks (docs/superpowers/specs/2026-10-02-deployment-design.md → Verification and
# V1–V5), and last the FLY_API_TOKEN repository secret that switches CI's deploys on.
#
# Every flyctl flag and dashboard label comes from
# docs/superpowers/research/2026-10-13-deployment-platforms.md (Part 4, plus Part 1 for flyctl);
# where that says UNVERIFIED, the step says "look for" instead of naming a label.
#
# Safe to re-run: each stage notices work already done. ENV_FILE holds only the two non-secret
# choices, FLY_APP and VERCEL_ORIGIN. The API keys go from a backend/.env straight into
# `fly secrets import` on stdin, and the deploy token from `fly tokens create` straight into
# `gh secret set` on stdin: neither is printed, passed in argv, or written to a file.
#
# Needs bash 3.2 (macOS's own) or later, curl, python3 (3.8+; no jq, no GNU sed), flyctl and gh.

REPO="lawry98/f1-application"
GH_OWNER="lawry98"
VERCEL_PROJECT="f1-race-briefing"
DEFAULT_ORIGIN="https://f1-race-briefing.vercel.app"
FORGED_IP="203.0.113.7"   # RFC 5737 documentation range: never a real visitor
ORIGIN_RE='^https://[a-z0-9]([a-z0-9.-]*[a-z0-9])?$'
APP_RE='^[a-z0-9]([a-z0-9-]*[a-z0-9])?$'
# uvicorn's access line: `INFO:     <client> - "GET …`, where <client> is scope["client"] as
# host:port — the address the cost guard keys on.
ACCESS_RE='INFO:[[:space:]]+([^[:space:]]+)[[:space:]]+-[[:space:]]+"'

[[ -t 0 ]] || { printf 'Run this in a terminal: it asks questions and opens a browser.\n' >&2; exit 1; }
ROOT=$(git rev-parse --show-toplevel 2>/dev/null) \
  || { printf 'Run this from inside the f1-application checkout.\n' >&2; exit 1; }
cd "$ROOT"
ENV_FILE=".env.deploy.local"   # gitignored by .env*.local — FLY_APP and VERCEL_ORIGIN, never a secret
WORK=$(mktemp -d)              # non-secret scratch (JSON listings, the test stream); removed on exit
trap 'rm -rf "$WORK"' EXIT
trap 'exit 130' INT TERM

# ── Helpers for these stages (the library above stays untouched) ──────────

ok()  { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
# bad "…" — a failed check: shown now, and listed again in the closing summary.
bad() { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET"; SKIPPED+=("FAILED: $1"); }
# halt "…" — stop: nothing after this point can work yet.
halt() {
  printf '\n'
  warn "$1"
  note "Fix that, then re-run scripts/deploy-wizard.sh — $ENV_FILE keeps the choices made so far."
  exit 1
}
pause_next() { pause "Press Enter for the next stage"; }

# report_failures — say how many bad() calls there were. finish() prints a green "Setup complete"
# whatever they recorded, and clears the screen first, so this runs before the last pause (it stays
# on that prompt) and again under the summary. Silent when nothing failed.
report_failures() {
  local entry failed=0
  for entry in "${SKIPPED[@]+"${SKIPPED[@]}"}"; do
    if [[ $entry == "FAILED: "* ]]; then failed=$((failed + 1)); fi
  done
  if (( failed )); then
    printf '\n  %s%s✗ %s check(s) failed — each is listed as FAILED in the summary%s\n' "$BOLD" "$RED" "$failed" "$RESET"
  fi
}

# part "Name" — a fresh screen inside the current stage, so the step in hand never scrolls away.
part() {
  _clear
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# relay — print a python check's "PASS|FAIL|INFO<TAB>text" lines as ok / bad / note. Fed by
# process substitution, never a pipe, so bad()'s SKIPPED entries land in this shell.
relay() {
  local kind text
  while IFS=$'\t' read -r kind text; do
    case "$kind" in
      PASS) ok "$text" ;;
      FAIL) bad "$text" ;;
      *) note "${text:-$kind}" ;;
    esac
  done
}

# ask_default KEY "Prompt" DEFAULT — ask, showing the saved value or else DEFAULT; Enter takes it.
ask_default() {
  local key="$1" prompt="$2" default="$3" current
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then ask "$key" "$prompt ($current)"; else ask "$key" "$prompt [$default]"; fi
  if [[ -z "${!key}" ]]; then printf -v "$key" '%s' "$default"; fi
}

# app_is_ours NAME — the app exists and this login can see it. `fly status` is the documented
# probe; `fly machines list` backs it up in case status ever fails on a never-deployed app.
app_is_ours() {
  fly status -a "$1" --json >/dev/null 2>&1 || fly machines list -a "$1" --json >/dev/null 2>&1
}

# http_code [curl args…] URL — the status code only; 000 when nothing answered.
http_code() { curl -s -o /dev/null -w '%{http_code}' --max-time 20 "$@" || true; }

# normalise_origin VALUE — lowercase, no trailing slash, https:// if no scheme was typed.
normalise_origin() {
  local o
  o=$(printf '%s' "$1" | tr '[:upper:]' '[:lower:]')
  while [[ "$o" == */ ]]; do o="${o%/}"; done
  if [[ "$o" != *://* ]]; then o="https://$o"; fi
  printf '%s' "$o"
}

# print_pr_steps BRANCH "commit message" — main only changes through pull requests.
print_pr_steps() {
  say "Commit it through a pull request:"
  printf '\n    git switch -c %s\n    git add fly.toml\n    git commit -m "%s"\n' "$1" "$2"
  printf '    git push -u origin %s\n    gh pr create --base main --fill\n\n' "$1"
  say "Once it is merged: git switch main && git pull --ff-only, then re-run scripts/deploy-wizard.sh."
}

# preflight_origin ORIGIN — the access-control-allow-origin a CORS preflight from ORIGIN gets.
preflight_origin() {
  curl -s -o /dev/null -D - --max-time 20 -X OPTIONS \
    -H "Origin: $1" -H 'Access-Control-Request-Method: POST' \
    -H 'Access-Control-Request-Headers: content-type' "$API/api/briefing/stream" \
    | tr -d '\r' | grep -i '^access-control-allow-origin:' | head -n 1 \
    | sed 's/^[^:]*:[[:space:]]*//;s/[[:space:]]*$//' || true
}

# ── Python helpers: the program is the heredoc, so every input is a file argument ──

# py_fly_toml get FILE KEY | set FILE KEY VALUE | env-upsert FILE KEY VALUE
# Reads or rewrites one `KEY = "value"` line in place. No tomllib: macOS's python3 is 3.9.
py_fly_toml() {
  python3 - "$@" <<'PY'
import os, re, sys
mode, path, key = sys.argv[1], sys.argv[2], sys.argv[3]
with open(path) as f:
    text = f.read()
line = re.compile(r'^(?P<lead>[ \t]*' + re.escape(key) + r'[ \t]*=[ \t]*)"(?P<val>[^"\n]*)"', re.M)
found = list(line.finditer(text))
if mode == "get":
    if len(found) != 1:
        sys.exit(1)
    print(found[0].group("val"))
    sys.exit(0)
value = sys.argv[4]
if any(c in value for c in '"\\\n\r'):
    sys.exit("refusing a value with a quote, backslash or line break")
if len(found) > 1:
    sys.exit("%s appears %d times in %s; edit it by hand" % (key, len(found), path))
if found:
    m = found[0]
    text = text[:m.start("val")] + value + text[m.end("val"):]
elif mode == "env-upsert":
    lines = text.split("\n")
    starts = [i for i, l in enumerate(lines) if l.strip() == "[env]"]
    if not starts:
        sys.exit("no [env] table in %s" % path)
    last = starts[0]
    for i in range(starts[0] + 1, len(lines)):
        s = lines[i].strip()
        if s.startswith("["):
            break
        if s and not s.startswith("#"):
            last = i
    lines.insert(last + 1, '  %s = "%s"' % (key, value))
    text = "\n".join(lines)
else:
    sys.exit("no %s line in %s" % (key, path))
with open(path + ".tmp", "w") as f:
    f.write(text)
os.replace(path + ".tmp", path)
PY
}

# py_env_secrets check|emit FILE — the three API keys from a backend/.env. `check` reports on
# stderr, names only. `emit` writes NAME="value" lines to stdout, which the caller pipes straight
# into `fly secrets import`; double quotes because Fly's parser cuts an unquoted value at `#`.
# Exits 2, printing nothing on stdout, on a missing GOOGLE_API_KEY or a value it will not quote.
py_env_secrets() {
  python3 - "$@" <<'PY'
import re, sys
mode, path = sys.argv[1], sys.argv[2]
NAMES = ("GOOGLE_API_KEY", "TAVILY_API_KEY", "OPENWEATHER_API_KEY")
REQUIRED = "GOOGLE_API_KEY"
PLACEHOLDER = re.compile(r"(tvly-)?your-[a-z0-9-]*")   # backend/config.py's is_configured
LINE = re.compile(r"^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*?)\s*$")
QUOTED = re.compile(r"""^(["'])(.*)\1(?:\s+#.*)?$""")
try:
    with open(path, encoding="utf-8") as f:
        lines = f.read().splitlines()
except (OSError, UnicodeDecodeError) as exc:
    sys.stderr.write("  cannot read %s: %s\n" % (path, exc))
    sys.exit(2)
values = {}
for raw_line in lines:
    m = LINE.match(raw_line)
    if not m or m.group(1) not in NAMES:
        continue
    raw = m.group(2)
    q = QUOTED.match(raw)
    if q:
        raw = q.group(2)                      # one pair of surrounding quotes
    else:
        raw = re.sub(r"\s+#.*$", "", raw)     # python-dotenv: an unquoted value's comment
    values[m.group(1)] = raw.strip()          # the last assignment wins, as in python-dotenv
keep, refused = {}, False
for name in NAMES:
    value = values.get(name, "")
    if any(c in value for c in '"\\\n\r'):
        sys.stderr.write("  %s: contains a double quote, backslash or line break - refusing it\n" % name)
        refused = True
    elif not value or PLACEHOLDER.fullmatch(value.lower()):
        state = "still the env.example placeholder" if value else "missing or empty"
        if name == REQUIRED:
            sys.stderr.write("  %s: %s - the backend cannot start without it\n" % (name, state))
            refused = True
        else:
            sys.stderr.write("  %s: %s - skipped; that feature stays off in production\n" % (name, state))
    else:
        keep[name] = value
if refused:
    sys.exit(2)
if mode == "check":
    sys.stderr.write("  found: %s\n" % ", ".join(keep))
else:
    for name, value in keep.items():
        sys.stdout.write('%s="%s"\n' % (name, value))
PY
}

# py_secret_names FILE [show] — names from `fly secrets list --json` (with status, for show).
py_secret_names() {
  python3 - "$@" <<'PY'
import json, sys
try:
    with open(sys.argv[1]) as f:
        rows = json.load(f) or []
except (OSError, ValueError):
    rows = []
show = sys.argv[2:] == ["show"]
for r in rows:
    if not isinstance(r, dict):
        continue
    name = r.get("name") or r.get("Name")
    if name:
        status = r.get("status") or r.get("Status") or ""
        print("%s\t%s" % (name, status) if show else name)
PY
}

